// skeleton/cmd/server/main.go
// Go 微服务主入口模板

package main

import (
    "context"
    "fmt"
    "log/slog"
    "net/http"
    "os"
    "os/signal"
    "syscall"
    "time"

    "github.com/{{ values.githubOrg }}/{{ values.serviceName }}/internal/config"
    "github.com/{{ values.githubOrg }}/{{ values.serviceName }}/internal/handler"
    {% if values.enableMetrics %}
    "github.com/prometheus/client_golang/prometheus/promhttp"
    {% endif %}
)

func main() {
    // 加载配置
    cfg, err := config.Load()
    if err != nil {
        slog.Error("failed to load config", "error", err)
        os.Exit(1)
    }

    // 初始化日志
    logLevel := slog.LevelInfo
    if cfg.Debug {
        logLevel = slog.LevelDebug
    }
    slog.SetDefault(slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{
        Level: logLevel,
    })))

    slog.Info("starting {{ values.serviceName }}",
        "version", cfg.Version,
        "port", cfg.Port,
    )

    // 初始化 HTTP 路由
    mux := http.NewServeMux()

    // 注册业务路由
    h := handler.New(cfg)
    h.RegisterRoutes(mux)

    {% if values.enableMetrics %}
    // Prometheus 指标端点
    mux.Handle("/metrics", promhttp.Handler())
    {% endif %}

    // 健康检查端点 (Kubernetes Liveness/Readiness Probe)
    mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
        w.WriteHeader(http.StatusOK)
        fmt.Fprintln(w, `{"status":"ok"}`)
    })

    mux.HandleFunc("/readyz", func(w http.ResponseWriter, r *http.Request) {
        // TODO: 添加依赖健康检查（数据库、外部服务等）
        w.WriteHeader(http.StatusOK)
        fmt.Fprintln(w, `{"status":"ready"}`)
    })

    // 启动 HTTP Server
    srv := &http.Server{
        Addr:         fmt.Sprintf(":%d", cfg.Port),
        Handler:      mux,
        ReadTimeout:  30 * time.Second,
        WriteTimeout: 30 * time.Second,
        IdleTimeout:  120 * time.Second,
    }

    // 优雅关闭
    quit := make(chan os.Signal, 1)
    signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)

    go func() {
        slog.Info("server started", "addr", srv.Addr)
        if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
            slog.Error("server error", "error", err)
            os.Exit(1)
        }
    }()

    <-quit
    slog.Info("shutting down server...")

    ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
    defer cancel()

    if err := srv.Shutdown(ctx); err != nil {
        slog.Error("server shutdown error", "error", err)
        os.Exit(1)
    }

    slog.Info("server stopped")
}

